#!/usr/bin/env node
/**
 * Validate `manifest/server-manifest.json` before it is trusted.
 *
 * The manifest is the authority on what to download and which checksum to
 * expect, so a mistake in it is a mistake in a security decision. Generated by
 * `scripts/gen-manifest.mjs` and hand-edited only rarely — which is exactly when
 * this check earns its keep:
 *
 *   * the schema version is one we know how to interpret;
 *   * every `channel.stable[platform]` names a version that exists, ships an
 *     asset for that platform, and can actually be downloaded;
 *   * no URL uses a scheme other than https;
 *   * `pluginCompat.minSupportedServer` is a version that exists.
 *
 * Exit code 1 on any problem, so `npm run build` fails rather than shipping a
 * manifest that would download the wrong file.
 */

import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const manifestPath = join(root, 'manifest', 'server-manifest.json')

const PLATFORMS = ['mac-arm64', 'mac-x64', 'linux-x64', 'linux-arm64', 'win-x64']
const problems = []
const warnings = []

function compareVersions(a, b) {
  const pa = a.split('-')[0].split('.').map(Number)
  const pb = b.split('-')[0].split('.').map(Number)
  for (let i = 0; i < 3; i += 1) {
    if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) - (pb[i] || 0)
  }
  return 0
}

let manifest
try {
  manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
} catch (error) {
  console.error(`无法读取 ${manifestPath}：${error.message}`)
  process.exit(1)
}

if (manifest.manifestVersion !== 1) {
  problems.push(`manifestVersion 应为 1，实际为 ${manifest.manifestVersion}`)
}
const versions = manifest.versions ?? {}
const versionKeys = Object.keys(versions)
if (versionKeys.length === 0) problems.push('versions 为空')

const allVersions = [...versionKeys].sort(compareVersions)

for (const [version, entry] of Object.entries(versions)) {
  if (typeof entry.releaseTag !== 'string' || entry.releaseTag === '') {
    problems.push(`${version}: 缺少 releaseTag`)
  }
  const assets = entry.assets ?? {}
  for (const [platform, list] of Object.entries(assets)) {
    if (!PLATFORMS.includes(platform)) {
      problems.push(`${version}: 未知平台键 ${platform}`)
      continue
    }
    if (!Array.isArray(list)) {
      problems.push(`${version}/${platform}: assets 不是数组`)
      continue
    }
    for (const asset of list) {
      if (typeof asset.file !== 'string' || asset.file === '') problems.push(`${version}/${platform}: 资产缺少 file`)
      if (!['zip', 'tar.gz', 'exe'].includes(asset.kind)) problems.push(`${version}/${platform}/${asset.file}: 未知 kind ${asset.kind}`)
      if (typeof asset.url !== 'string' || !asset.url.startsWith('https://')) {
        problems.push(`${version}/${platform}/${asset.file}: url 必须是 https://`)
      }
      if (asset.sha256 !== null && !/^[0-9a-f]{64}$/.test(String(asset.sha256))) {
        problems.push(`${version}/${platform}/${asset.file}: sha256 格式不正确`)
      }
      if (typeof asset.size !== 'number' || asset.size <= 0) {
        warnings.push(`${version}/${platform}/${asset.file}: size 缺失或为 0`)
      }
    }
  }
}

for (const platform of PLATFORMS) {
  const stable = manifest.channel?.stable?.[platform] ?? null
  if (stable === null) {
    warnings.push(`${platform}: channel.stable 为空（该平台没有可用版本）`)
    continue
  }
  if (!(stable in versions)) {
    problems.push(`${platform}: channel.stable 指向不存在的版本 ${stable}`)
    continue
  }
  const list = versions[stable]?.assets?.[platform] ?? []
  if (list.length === 0) {
    problems.push(`${platform}: channel.stable=${stable} 但该版本没有 ${platform} 资产`)
    continue
  }
  const primary = list[0]
  if (primary.sha256 === null) {
    warnings.push(`${platform}: 默认版本 ${stable} 的 ${primary.file} 没有校验值，安装时需用户显式确认`)
  }
  if (versions[stable].releaseTag === undefined) {
    problems.push(`${platform}: 版本 ${stable} 缺少 releaseTag`)
  }
}

const min = manifest.pluginCompat?.minSupportedServer
if (typeof min !== 'string' || !(min in versions)) {
  problems.push(`pluginCompat.minSupportedServer=${min} 不在 versions 中，升级门槛会永远拒绝或永远放行`)
}

const worst = allVersions[0]
if (worst !== undefined && typeof min === 'string' && compareVersions(min, worst) < 0) {
  warnings.push(`minSupportedServer=${min} 低于清单中最老的版本 ${worst}`)
}

for (const line of warnings) console.log(`  warn  ${line}`)
if (problems.length > 0) {
  for (const line of problems) console.error(`  error ${line}`)
  console.error(`清单校验失败：${problems.length} 个错误，${warnings.length} 个警告`)
  process.exit(1)
}
console.log(`  清单 ok：${allVersions.length} 个版本（${allVersions[0]} … ${allVersions.at(-1)}），${warnings.length} 个警告`)
